\label{rem:minimum-attained}
The previous variational problems we have seen all concern continuous functions on compact subsets of finite-dimensional Euclidean space, so they clearly each attain a minimum value. Here, it is less obvious that minimum values are actually attained.
To prove this, one should work with a particular metric called the \emph{cut metric} (see e.g.\ \cite{Lov12}). One can check that, with respect to the cut metric topology: the space of symmetric measurable functions $W:[0,1]^2\to [0,1]$ is compact (modulo measure-preserving relabellings), $t_H(W)$ is a continuous function of $W$, and $\int W(x,y)\log W(x,y)\operatorname dy\operatorname dx$ is a lower semicontinuous function of $W$. These facts together imply that a minimum value is attained in the variational problem in (1). To prove the same for (2), one needs an additional argument (along the lines of \cref{lem:truncation-lower}) to reduce to a variational problem over \emph{bounded} $W$. However, this will not actually be needed for any of the applications in this paper.

\label{thm:H-early}
    Let $H$ be a strictly 2-balanced graph with $e(H)=h$ and $|\operatorname{Aut}(H)|=a$, and let $0< c\le (ae/(2h))^{1/(h-1)}$. Then
    \[\Psi_{\operatorname{Bin}}(H,c,0)=\min_{s\in [0,1]}\bigg({s\log s-s+1+\frac{2c^{e(H)-1}}{|\operatorname{Aut}(H)|}s^{e(H)}}\bigg).\]

\label{thm:triangles}
For all $c> 0$ we have
\[\Psi_{\operatorname{Bin}}(K_3,c,0)=\min_{r,t\in [0,1]}\Bigg(\frac{(r\log r-r+1)+(t\log t-t+1)}2+\frac{c^2}{3}\bigg(\frac14r^3+\frac34rt^2\bigg)\Bigg).\]

\label{thm:H-late}
    Let $H$ be a strictly 2-balanced edge-critical graph with chromatic number $k+1$. Then there is $c_H>0$ such that the following holds. For all $c\ge c_H$ we have
\[\Psi_{\operatorname{Bin}}(H,c,0)=\min_{r,t\in [0,1]}\Bigg(\frac1k(r\log r-r+1)+\bigg(1-\frac1k\bigg)(t\log t-t+1)+\frac{2c^{e(H)-1}}{|\operatorname{Aut}(H)|}t_H(W_{r,t}^{(k)})\Bigg).\]

\label{def:bounded}
Say that an $N$-vertex $r$-uniform hypergraph $\mathcal{H}$ is \emph{$(\lambda,C;p)$-degree-bounded}
if
\begin{align*}
\Delta_{1}(\mathcal{H}) \le C p^{1-r},\qquad 
\Delta_{s}(\mathcal{H}) \le C \lambda p^{s-r}\text{ for all }s\in\{2,\dots,r-1\},\qquad 
\Gamma(\mathcal H)\le C\lambda p^{1-r}.
\end{align*}

\label{def:books}
Let $\mathcal H$ be a hypergraph on the vertex set $V$. An $a$-\emph{book} in $\mathcal H$ is a \emph{spine} vertex $v$ and a sequence of distinct hyperedges $(e_1,\dots,e_a)$ of $\mathcal H$ (its \emph{pages}) which all contain $v$. The \emph{page vertices} of the book are the vertices in $(e_1\cup \dots\cup e_a)\setminus v$ (note that a page vertex can be in more than one page). Then,
\begin{itemize}
    \item For $a,k\in \mathbb N$ and $v\in V$, let $\operatorname{bk}^a_k(\mathcal H;v)$ be the $k$-uniform multihypergraph defined as follows. For each $a$-book which has spine $v$ and exactly $k$ page vertices, put this set of page vertices as a hyperedge of $\operatorname{bk}^a_k(\mathcal H;v)$. (Note that, if $\mathcal H$ is $r$-uniform, such an $a$-book can only exist if $k\le a(r-1)$).
    \item We denote by $\operatorname{bk}^a_k(\mathcal H)$ the $k$-uniform multihypergraph obtained as the multiset union of $\operatorname{bk}^a_k(\mathcal H;v)$ for each $v\in V$. 
\end{itemize}

\label{lem:book-deg}
    Assume that $\mathcal H$ is $(\lambda, C;p)$-degree-bounded, for $\lambda\le 1$, and consider any $A\in \mathbb N$. Then for all $a\le A$,
    \begin{align}
        \Delta_s(\operatorname{bk}^a_k(\mathcal H))&\le O_{A,C,r}(1)\cdot (\lambda^{1/(Ar)} p)^{s-1}\cdot 
    p^{-k}\text{ for }s\in \{1,\dots,k\},\label{eq:book-degrees-goal-3}\\
        |\operatorname{bk}^a_k(\mathcal H;v)|&\le O_{A,C,r}(1)\cdot p^{-k}\text{ for all }v\in V.\label{eq:book-degrees-goal-1}
    \end{align}
    Moreover, for $k<a(r-1)$ we have
    \begin{equation}
    |\operatorname{bk}^a_k(\mathcal H;v)|\le O_{A,C,r}(1)\cdot \lambda\cdot p^{-k}\text{ for all }v\in V.\label{eq:book-degrees-goal-2}
    \end{equation}

\label{fact:entropy}
    The following hold for any random sequence $(X_1,\dots,X_L)$.
    \begin{itemize}
        \item (Chain rule) $\operatorname{H}[X_1,\dots,X_L]=\sum_{\ell=1}^L\operatorname H[X_\ell\,|\,X_1,\dots,X_{\ell-1}]$
        \item\vspace{5pt} (Subadditivity) $\operatorname{H}[X_1,\dots,X_L]\le \sum_{\ell=1}^L\operatorname H[X_\ell]$.
    \end{itemize}

\label{thm:KS}
    Consider $r_0,C_0, \alpha, \xi > 0$. There exists $\theta>0$ and $N_0\in \mathbb N$ such that the following holds. 
    Let $V$ be a ground set of size $N\ge N_0$, let $p\in(0,1/2)$ and let $\mathcal D$ be a nontrivial decreasing property. Let $Y$ be a sample from $\operatorname{Bin}(V,p)$, conditioned on the event $\mathcal D$. Then there exists $W \subseteq V$ with $|W| \le \alpha N$ such that, for any $k$-uniform hypergraph $\mathcal G$ equipped with nonnegative weights on its hyperedges, with $k\le r_0$, satisfying\footnote{Here $\Delta_s(\mathcal G)$ should be interpreted in a weighted sense (we define $\deg_\mathcal G(S)$ to be the sum of $\operatorname{wt}_\mathcal G(e)$ over all $e\supseteq S$).}
    \begin{equation}
        \Delta_s(\mathcal G) \le C_0 (\theta p)^{s-1} p^{-k}\text{ for all }s\in \{1,\dots,k\},\label{eq:KS-degree-condition}
    \end{equation}
    we have    
    \[
        \mathbb E \Bigg [\sum_{e\in\mathcal G[V\setminus W]} \operatorname{wt}_{\mathcal G}(e) \bigg|\mathbb E[\mathbbm{1}_{e\subseteq Y} \mid Y\cap W] - \prod_{v\in e} \mathbb E[\mathbbm{1}_{v\in Y} \mid Y\cap W]\bigg|\Bigg] \le \xi N,
    \]
    where we write $\operatorname{wt}_\mathcal G(e)$ for the weight in $\mathcal G$ of a hyperedge $e$.

\label{lem:moment}
        For $M, \beta>0$, there exist $A, \gamma>0$ such that the following holds. Let $\mathcal F$ be a sigma-algebra, let $(D_v)_{v\in V}$ be a collection of nonnegative integer valued random variables, and let $(\mu_v)_{v\in V}$ be a collection of $\mathcal F$-measurable random variables supported in $[0,M]$. Suppose that for all $a\in \{1,\dots,A\}$ we have
        \begin{equation*}
            \mathbb E\Bigg[\sum_{v\in V} \Big|\mathbb E[D_v(D_v-1)\dots (D_v-a+1)\,|\,\mathcal F] - \mu_{v}^a\Big| \Bigg]\le \gamma |V|. 
        \end{equation*}
        Then, we have 
        \[
            \mathbb E\Bigg[\sum_{v\in V} \mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big|\mathbb P[D_v=0\,|\,\mathcal F] - \exp(-\mu_{v})\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big| \Bigg] \le \beta|V|. 
        \]

\label{lem:seq-ent-tilted}
Let $\mathcal H$ be an $r$-uniform hypergraph on the vertex set $V$, and let $X\subseteq V$ be a random subset of $V$. For $v\in V$ and $S\subseteq V$, let $D_v(S)$ be the number of hyperedges $e\in \mathcal H$ containing $v$ such that $e\setminus v\subseteq S$.

Let $T\in \mathbb N$. Independently from $X$, consider a uniformly random partition of $V$ into $T$ sets $V_1,\dots,V_T$. Let $X_t=X\cap V_t$ and $X_{<t}=X_1\cup\dots\cup X_{t-1}$. Then, for every $\tau\ge 0$,
\begin{equation}
    \operatorname H[X]-\tau\mathbb E|\mathcal H[X]|
    \le\frac1T
    \sum_{t=1}^T\sum_{v\in V}
    \mathbb P[v\in X]
    \Big(
        1-\log \mathbb P[v\in X]
        +\log \mathbb E \exp(-\tau D_v(X_{<t}))
    \Big).
    \label{eq:seq-ent-tilted}
\end{equation}

As in the proof of \cref{lem:seq-ent}, by the chain rule and
subadditivity we have
\begin{equation}
    \operatorname H[X]+\mathbb E|X|\log T
    \le \sum_{t=1}^T\sum_{v\in V}\mathbb E h(Q_{v,t}),
    \label{eq:tilted-chain-rule}
\end{equation}
where $Q_{v,t}=\mathbb P[v\in X_t\mid X_{<t}]$.

Now, note that 
\[|\mathcal H[X]|\ge \sum_{t=1}^T\sum_{v\in V}
     \mathbbm{1}_{\{v\in X_t\}}D_v(X_{<t}).\]
Indeed, this sum counts hyperedges of $\mathcal H[X]$ which have a single vertex in $X_t$, and all other vertices in $X_{<t}$, for some $t$. So, recalling \cref{eq:tilted-chain-rule}, and noting that $\mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[\mathbbm{1}_{\{v\in X_t\}}D_v(X_{<t})\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]=\mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[Q_{v,t}D_v(X_{<t})\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]$, we have
\begin{equation}
    \operatorname H[X]-\tau\mathbb E|\mathcal H[X]|\le
\sum_{t=1}^T\sum_{v\in V}\mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[h(Q_{v,t})-\tau D_v(X_{<t})Q_{v,t}\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]
-\mathbb E|X|\log T.\label{eq:tilted-entropy-intermediate}
\end{equation}
We next need an upper bound on $\mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[h(Q_{v,t})-\tau D_v(X_{<t})Q_{v,t}\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]$, using the fact that $\mathbb EQ_{v,t}=\mathbb P[v\in X_t]=\mathbb P[v\in X]/T$. We do this by introducing a Lagrange multiplier. Indeed, letting $a_v=\mathbb P[v\in X]/T$, for any $\theta\in \mathbb R$ we have
\begin{align}
    \mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[h(Q_{v,t})-\tau D_v(X_{<t})Q_{v,t}\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]&= \mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[h(Q_{v,t})-\tau D_v(X_{<t})Q_{v,t}\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]+\theta(\mathbb EQ_{v,t}-a_v)\notag\\
    &=-\theta a_v+\mathbb E\Big[h(Q_{v,t})+\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big(\theta-\tau D_v(X_{<t})\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big)Q_{v,t}\Big]\notag\\
    &\le  -\theta a_v+\mathbb E\Big[\log\Big(1+\exp\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big(\theta-\tau D_v(X_{<t})\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big)\Big)\Big]\notag\\
    &\le  -\theta a_v+\mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[\exp\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big(\theta-\tau D_v(X_{<t})\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big)\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]\notag\\
    &=-\theta a_v+e^\theta\mathbb E\exp(-\tau D_v(X_{<t})),\label{eq:lagrange}
\end{align}
where we have used that $\sup_{q\in [0,1]}(h(q)+sq)=h(q_s)+s q_s=\log(1+e^{s})$ for $q_s=e^s/(1+e^s)$ (which is a simple calculus exercise), and the elementary inequality $\log(1+x)\le x$.

Now, we take\footnote{This is not well-defined if $a_v=\mathbb P[v\in X]=0$, but then we can simply remove $v$ from $V$ (it is irrelevant for the lemma).} $\theta=\log a_v-\log \mathbb E\exp(-\tau D_v(X_{<t}))$ (this is the choice of $\theta$ that minimises the expression in \cref{eq:lagrange}), and obtain
\[\mathbb E\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[h(Q_{v,t})-\tau D_v(X_{<t})Q_{v,t}\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]\le a_v\Big(1-\log a_v+\log\mathbb E\exp(-\tau D_v(X_{<t}))\Big).\]
We then substitute this into \cref{eq:tilted-entropy-intermediate}. Recalling that $a_v=\mathbb P[v\in X]/T$ and $\mathbb E|X|=\sum_{v\in V}\mathbb P[v\in X]$, the desired result follows.

\label{fact:Phi}
For all $L\ge 0$ and $M>0$, we have
\begin{enumerate}
    \item $(1-e^{-1})M\le L+\Phi_L(M)$,
\item $\Phi_L'(M)=\max(0,1-L/M)\in[0,1]$.
\end{enumerate}

We may assume that $y=\Omega(1)$, as the $y=o(1)$ case is implied by \cref{thm:GW-lower-bound} (since $\phi(o(1))=1-o(1)$).

    Let $\mathcal G'$ be a random subhypergraph of $\mathcal G$ obtained by including each hyperedge with probability $y$ independently, and let $\mathcal G''=\mathcal G\setminus \mathcal G'$. Then (e.g., by a Chernoff bound), with probability $1-o(1)$ we have $\mathcal G'(\alpha)=y\mathcal G(\alpha)+o(\alpha N)$ and $(\mathcal G\setminus \mathcal G')(\alpha)=(1-y)\mathcal G(\alpha)+o(\alpha N)$. Say such an outcome of $\mathcal G'$ is ``good''.

    Now, we apply \cref{thm:GW-lower-bound} to $\mathcal G\setminus \mathcal G'$, using the test hypergraph\footnote{Using the fact that $\mathcal G$ is $(N^{-\nu},C;\alpha)$-degree-bounded, it is easy to verify that $\mathcal G'$ satisfies the requirements for being a test hypergraph, unless $|\mathcal G'(\alpha)|=O(1)$. In this case, add a tiny number of ``fake hyperedges'' to $\mathcal G'$ (this will not affect any of the following estimates).} $\mathcal G'$ in addition to $\mathcal F_1,\dots,\mathcal F_Q$. This tells us that if $\mathcal G'$ is good then there is $m(\mathcal G')=(1+o(1))\alpha N$ and a family $\mathcal A(\mathcal G')$ of at least 
    \[\binom{N}{m(\mathcal G')}\exp\Big(-(1-y)\mathcal G(\alpha)-o(\alpha N)\Big)\]
    size-$m(\mathcal G')$ sets $X\subseteq V$ satisfying $|(\mathcal G\setminus \mathcal G')[X]|=0$ and $|\mathcal F_i[X]|=(1+o(1))\alpha^{k_i}|\mathcal F_i|$ for each $i\in\{1,\dots,Q\}$, and 
    $|\mathcal G'[X]|=\alpha^{r}|\mathcal G'|+o(\alpha N)=y\mathcal G(\alpha)+o(\alpha N)$. In particular, all such sets satisfy $|\mathcal G[X]|\le y\mathcal G(\alpha)+o(\alpha N)$.

    Since there are only $N=\exp(o(\alpha N))$ possibilities for $m$, there must be some value of $m$ such that 
    \begin{equation}
        \mathbb E|\mathcal A_m(\mathcal G')|\ge \binom{N}{m}\exp\Big(-(1-y)\mathcal G(\alpha)-o(\alpha N)\Big),\label{eq:red-blue-pigeonhole}
    \end{equation}
    where the expected value is over the randomness of $\mathcal G'$, and
    \[\mathcal A_m(\mathcal G')=\begin{cases}
        \mathcal A(\mathcal G')&\text{if }m(\mathcal G')=m\text{ and }\mathcal G'\text{ is good},\\
        \emptyset&\text{if }m(\mathcal G')\ne m\text{ or }\mathcal G'\text{ is not good}.
     \end{cases}\]
     On the other hand, let $\mathcal A_m$ be the collection of \emph{all} size-$m$ subsets $X\subseteq V$ satisfying $|\mathcal G[X]|= y\mathcal G(\alpha)\pm \varepsilon\alpha N$ and $|\mathcal F_i[X]|=(1\pm \varepsilon)\alpha^{k_i}|\mathcal F_i|$ for each $i\in\{1,\dots,Q\}$, where $\varepsilon=o(1)$ is such that $\mathcal A_m(\mathcal G')\subseteq \mathcal A_m$ for all $\mathcal G'$. We have
     \begin{equation}
         \mathbb E|\mathcal A_m (\mathcal G')|\le \sum_{X\in \mathcal A_m}y^{|\mathcal G[X]|}=|\mathcal A_m|\exp\Big(y\mathcal G(\alpha)\log y+o(\alpha N)\Big).\label{eq:lutz-subsample}
     \end{equation}
     The desired lower bound on $|\mathcal A_m|$ then follows from \cref{eq:red-blue-pigeonhole,eq:lutz-subsample}.

First, note that we can assume $L< \mathcal H(m/N)$. Indeed, if $L\ge \mathcal H(m/N)$ it is easy to see that the unique minimiser is the constant weighting $(m/N)\vec 1\in [0,1]^V$ (by strict convexity of $\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,m/N)$, and the fact that $\Phi_L(M)=0$ for $L\ge M$). So, by $(N^{-\nu},C;m/N)$-degree-boundedness we have
 \begin{equation}
      L\le O_C(m).\label{eq:L-bound-2}
  \end{equation}

Now, let $p=m/N$. The dependence of $A$ on $C,r$ will be moderated by an additional parameter $B$ (we need $B$ to be large in terms of $C,r$, and $A$ to be large in terms of $B,C,r$).

The plan is to show that if there were $v$ such that $q_v>Ap$, then we would be able to transfer some weight from $v$ to some other $w$ to decrease the value of $\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,m/N)+\Phi_L(\mathcal H(\vec q))$ (and since we are assuming $\vec q$ is a minimiser, this is impossible).

First, we need to find a suitable vertex $w$. Since we are assuming that $\vec q$ is a minimiser, we have \[\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,p)+\Phi_L(\mathcal H(\vec q))\le \operatorname{D}_{\mathrm{KL}}(p\vec 1\,\|\,p)+\Phi_L(\mathcal H(p\vec 1))=O_{C,r}(pN),\]where we write $p\vec 1$ for the vertex-weighting that gives every vertex a weight of exactly $p=m/N$, and we used $(N^{-\nu},C;p)$-degree-boundedness. In particular, we have 
\begin{align}
    \operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,p)&\le O_{C,r}(pN),\label{eq:Dq-bound}\\
    \Phi_L(\mathcal H(\vec q))&\le O_{C,r}(pN).\label{eq:Hq-bound-pre}
\end{align}
Then, we can use \cref{fact:Phi}(1) with \cref{eq:L-bound-2,eq:Hq-bound-pre} to see that
\begin{equation}
        \mathcal H(\vec q)\le O_{C,r}(pN).\label{eq:Hq-bound}
\end{equation}
Let $i_p(q)=q\log(q/p)+(1-q)\log((1-q)/(1-p))$, and note that if $q\ge Bp$ then $i_p(q)\ge q(\log B-1)$. So, using \cref{eq:Dq-bound} we have
\begin{equation}
    \sum_{v:q_v\ge Bp}q_v\le \sum_{v:q_v\ge Bp}\frac{i_p(q_v)}{\log B-1}\le \frac{\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,p)}{\log B-1}\le \frac m2\label{eq:truncation-few}
\end{equation} if $B$ is sufficiently large in terms of $C,r$.

Then, let
\[h_v=\frac{\partial}{\partial q_v}\mathcal H(\vec q)=\sum_{\substack{e\in \mathcal H:\\e\owns v}}\prod_{u\in e\setminus v}q_u.\]
Using \cref{eq:truncation-few} and \cref{eq:Hq-bound}, we have
\[\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\sum_{v:q_v< Bp}q_vh_v\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)/\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\sum_{v:q_v< Bp}q_v\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)\le \frac 2m\sum_{v\in V}q_vh_v=\frac{2r}m\mathcal H(\vec q)=O_{C,r}(1).\]
(We can assume the left-hand side is not dividing by zero, or we are already done).

So, there is $w\in V$ such that $q_w<Bp$ and $h_w=O_{C,r}(1)$. Now, suppose for the purpose of contradiction there is $v$ such that $q_v>Ap$. If we were to move some weight from $v$ to $w$, the derivative of the effect on $\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,p)+\Phi_L(\mathcal H(\vec q))$ would be
\begin{align*}
    &\bigg(\frac{\partial}{\partial q_w}i_p(q_w)+\theta h_w\bigg)-\bigg(\frac{\partial}{\partial q_v}i_p(q_v)+\theta h_v\bigg)\\&\qquad=\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big(\log q_w-\log(1-q_w)\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big)-\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big(\log q_v-\log(1-q_v)\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big)+ \theta(h_w-h_v)\\&\qquad\le \log B-\log A+O_C(B)
    \end{align*}
where $\theta=\Phi_L'(\mathcal H(\vec q))\in [0,1]$. This derivative is negative for large $A$, which contradicts the minimality of $\vec q$.

\label{prop:H-free}
For a strictly 2-balanced graph $H$ which is not the 2-edge path, let $\mathcal H_H$ be the $e(H)$-uniform hypergraph on $N=\binom n2$ vertices, which has a vertex for each edge of the complete graph $K_n$, and a hyperedge for every copy of $H$ in $K_n$.

Fix $\delta>0$ and suppose that $\delta n^{-1/d_{2}(H)}\le p\le \delta^{-1}n^{-1/d_{2}(H)}$. Then, there is $\nu_H>0$ and $C_{\delta,H}>0$ such that $\mathcal H_H$ is $(N^{-\nu_H},C_{\delta,H};p)$-degree-bounded.

\label{lem:approximate-weighting-with-graphon}
Recall the notation from \cref{thm:main-graphs,cor:main-graphs}, and let $N=\binom n2$.
\begin{enumerate}
    \item In the setting of \cref{cor:main-graphs}(1): for any $\vec q\in \mathcal Q$ there is $W\in \mathcal W$ such that
\begin{align*}
        &p\binom n2\cdot \bigg(
        \int(W\log W-W+1)+\frac{2c^{e(H)-1}}{|\operatorname{Aut}(H)|}\psi_z(t_H(W))\bigg) \\
        &\qquad\qquad=   \operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,p)+\Phi_L(X_H(\vec q))+o(pN).
    \end{align*}
    \item In the setting of \cref{cor:main-graphs}(2): for any $\vec q\in \mathcal Q_m$ satisfying $\|\vec q\|_\infty =O(m/N)$ there is $W\in \tilde{\mathcal W}$ such that
\[
        m\cdot \bigg(
        \int W\log W+\frac{2c^{e(H)-1}}{|\operatorname{Aut}(H)|}\psi_z(t_H(W))\bigg)= \operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,m/N)+\Phi_L(X_H(\vec q))+o(m).
    \]
\end{enumerate}

\label{lem:approximate-graphon-with-weighting}
Recall the notation from \cref{thm:main-graphs,cor:main-graphs}, and let $N=\binom n2$.
\begin{enumerate}
    \item In the setting of \cref{cor:main-graphs}(1): for any $W\in \mathcal W$ there is $\vec q\in \mathcal Q$ such that
\begin{align*}
        &\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,p)+\Phi_L(X_H(\vec q)) \\
        &\qquad\qquad=   p\binom n2\cdot \bigg(
        \int(W\log W-W+1)+\frac{2c^{e(H)-1}}{|\operatorname{Aut}(H)|}\psi_z(t_H(W))\bigg)+o(pN).
    \end{align*}
    \item In the setting of \cref{cor:main-graphs}(2): for any $W\in \tilde{\mathcal W}$ satisfying $\int W\log W<\infty$ and $t_H(W)<\infty$,
    there is $\vec q\in \mathcal Q_m$ such that
\[
        \operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,m/N)+\Phi_L(X_H(\vec q))= m\cdot \bigg(
        \int W\log W+\frac{2c^{e(H)-1}}{|\operatorname{Aut}(H)|}\psi_z(t_H(W))\bigg)+o_W(m).
    \]
\end{enumerate}

Suppose the conclusion of the lemma were false. Then, there would be a sequence of values of $\gamma$, tending to $\infty$, and a corresponding sequence of $\Psi_\gamma$-minimisers $W_\gamma$, for which $\operatorname d_\square(W_\gamma,G_k)> \delta$. By compactness, there would be an infinite subsequence along which $W_\gamma$ converges (in the cut metric) to a limit $W_*$ satisfying $\operatorname d_\square (W_*,G_k)\ge \delta$. We will show this is impossible: for any sequence of values of $\gamma$ tending to $\infty$, and any corresponding sequence of $\Psi_\gamma$-minimisers $W_\gamma$ tending to a limit $W_*$, we must have $\operatorname d_\square(W_*,G_k)=0$.

To see this, first note that since $W_\gamma$ minimises $\Psi_\gamma$, we must have 
\[\int g(W_\gamma)+\gamma t_H(W_\gamma)= \Psi_\gamma(W_\gamma)\le \Psi_\gamma(G_k)=1/k. \]
This implies that $t_H(W_\gamma)\le 1/(k\gamma)\to 0$, so $t_H(W_*)=0$. It also implies that 
\begin{equation}
    \int g(W_*)\le 1/k\label{eq:gW*}
\end{equation}
(by lower-semicontinuity of $W\mapsto \int g(W)$).

Since $t_H(W_*)=0$, the stability version of the Erd\H os--Stone--Simonovits theorem~\cite{Sim68} tells us that the support graphon $\mathbbm{1}_{W_*>0}$ satisfies
\[\int (1-g(W_*))\le \int \mathbbm{1}_{W_*>0}\le 1-1/k,\] with equality only when $W_*=\mathbbm{1}_{W_*>0}$ almost everywhere\footnote{i.e., for all but a measure-zero set} and $\operatorname d_\square(W_*,G_k)=0$. Recalling \cref{eq:gW*}, this means that $\int g(W_*)= 1/k$ and $\operatorname d_\square(W_*,G_k)=0$.

\label{lem:strong-stability}For every $\Psi_{\gamma}$-minimiser
$W$ there is a partition $I_1\cup \dots\cup I_k$ such that:
\begin{enumerate}
\item each part $I_i$ has measure $1/k+o(1/k)$.
    \item $W(x,y)\le \exp(-\Omega_H(\gamma))$
    for almost every $x,y$ in the same part $I_i$,
    \item $W(x,y)\ge 1-\exp(-\Omega_H(\gamma))$ for almost every $x,y$ in two different parts $i,j$,
\end{enumerate}
where asymptotics are as $\gamma\to \infty$.

\label{def:book-STS}
Let $G,\mathcal H_4,\mathcal H_2,\mathcal H$ be as in \cref{def:STS-H}. Fix an ordering on the pairs of vertices of $G$, so for each $v=xyz\in K=\operatorname V(\mathcal H)$ we can write $v[1]<v[2]<v[3]$ for the three pairs $xy,xz,yz\in G$, labelled according to our fixed ordering.

For $a\in \mathbb N_{\ge 0}$ and $Q\subseteq \{1,2,3\}$, an \emph{$(a,Q)$-book} is a spine vertex $v\in \operatorname V(\mathcal H)=K$, a sequence of distinct
hyperedges $(h_{1},\dots,h_{a})$ of $\mathcal{H}_{4}$ containing $v$, and a choice of a triple $u_i\in K\setminus v$ containing $v[i]$ for each $i\in Q$. The \emph{page vertices} of the $(a,Q)$-book are the vertices $u_i\in \operatorname V(\mathcal H)$ for $i\in Q$, together with the vertices in $(h_1\cup \dots \cup h_a)\setminus v$ (note that these two types of page vertices are always disjoint).
 \begin{itemize}
\item For $a,k\in \mathbb N_{\ge 0}$ and $Q\subseteq \{1,2,3\}$ and $v\in V$, let $\operatorname{bk}^{a,Q}_k(\mathcal H;v)$ be the $k$-uniform multihypergraph defined as follows. For each $(a,Q)$-book which has spine $v$ and exactly $k$ page vertices, put this set of page vertices as a hyperedge of $\operatorname{bk}^{a,Q}_k(\mathcal H;v)$.
    \item Denote by $\operatorname{bk}^{a,Q}_k(\mathcal H)$ the $k$-uniform multihypergraph obtained as the multiset union of $\operatorname{bk}^{a,Q}_k(\mathcal H;v)$ for each $v\in V$.
    \end{itemize}

\label{lem:book-degrees-STS}
Let $\mathcal H_4,\mathcal H_2,\mathcal H$ be as in \cref{def:STS-H}. Then, for any $A\in\mathbb N$, any $a\le A$, any $Q\subseteq\{1,2,3\}$ and any $k\le3a+|Q|$,
we have
\begin{align}
    \Delta_s(\operatorname{bk}^{a,Q}_k(\mathcal H))&\le O_{A}(1)\cdot (o(1/n))^{s-1}\cdot 
    n^{k}\text{ for }s\in \{1,\dots,k\},\label{eq:book-degrees-goal-3-STS}
    \\
    |\operatorname{bk}^{a,Q}_k(\mathcal H;v)|&\le O_{A}(1)\cdot n^{k}\text{ for all }v\in V.\label{eq:book-degrees-goal-1-STS}
    \end{align}
    Moreover, for $k<3a+|Q|$ we have
    \begin{equation}
        |\operatorname{bk}^{a,Q}_k(\mathcal H;v)|\le O_{A}(1)\cdot o(1)\cdot n^{k}\text{ for all }v\in V.\label{eq:book-degrees-goal-2-STS}
    \end{equation}

As in \cref{subsec:uniform-random-upper}, let $p=Bm/N$ for some large $B$ (we need it to be large in terms of $\varepsilon$). Let $a_B=\log B+\log(1-m/N)-\log(1-p)$ and 
\[
I_B(\vec{q})=\operatorname{D}_{\mathrm{KL}}(\vec{q}\,\|\,m/N)+\mathcal{H}_4(\vec{q})+a_B(m-|\vec{q}|).
\]
The same considerations as in the proof of \cref{thm:main-m-upper} (in \cref{subsec:uniform-random-upper}), using \cref{lem:STS-reduction-p} in place of \cref{thm:main-upper-general}, show that
\[\log\mathbb P\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big[|\mathcal{H}[R]|=0\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\mathopen{}\mathclose\big]\le-\min_{\vec{q}\in \mathcal Q^*}\Bigg(I_B(\vec{q})+\sum_{g\in G}\chi(\ell_g(\vec q))\Bigg)+(\varepsilon/2)m.\]
So, to prove the theorem, it suffices to show that
\begin{equation}
\min_{\vec{q}\in \mathcal Q^*}\Bigg(I_B(\vec{q})+\sum_{g\in G}\chi(\ell_g(\vec q))\Bigg)\ge\min_{\vec{q}\in[0,1]^{\operatorname V(\mathcal H)}:|\vec{q}|=m}I_B(\vec{q})+3m-(\varepsilon/2)m.\label{eq:goal-STS-binomial-reduction}    
\end{equation}

Consider any $\vec{q}\in \mathcal Q^*$;
it suffices to find $\vec{s}$ satisfying $|\vec{s}|=m$ such that
$I_B(\vec{q})+\sum_{g\in G}\chi(\ell_g(\vec q))\ge I_B(\vec{s})+3m-(\varepsilon/2)m$. Suppose that the constant weighting $(m/N)\vec 1$ does not do the job: namely, suppose 
\[
  I_B(\vec{q})+\sum_{g\in G}\chi(\ell_g(\vec q))<I_B((m/N)\vec 1)+3m=\mathcal H_4(m/N)+3m
  \]
  (here we are using $|G|=3m$ and $\chi(\ell_g((m/N)\vec 1))=\chi(1)=1$). Since $\mathcal H_4$ is $(\lambda,O(1);m/N)$-bounded, we have $\mathcal H_4(m/N)=O(m)$, so $a_B(m-|\vec q|)\le I_B(\vec q)\le O(m)$. Since $a_B=\Omega(\log B)$, we deduce
\begin{align}
m-|\vec{q}| &\le O(m/\log B),\label{eq:m-1-STS}\\
\mathcal{H}_4(\vec{q}) & \le O(m).\label{eq:m-2-STS}    
\end{align}
Now, let $\theta=m/|\vec q|$ (so $|\theta\vec q|=m$). 
In Step~3 of the proof of \cref{thm:main-m-upper} (in \cref{subsec:uniform-random-upper}), we showed how to use \cref{eq:m-1-STS} and \cref{eq:m-2-STS} to prove that 
\begin{equation}
    I_B(\vec{q})\ge I_B(\theta\vec q)-(\varepsilon/4)m\label{eq:previous-step-3}
\end{equation} (we proved this with ``$\varepsilon/2$'' in place of ``$\varepsilon/4$'', but the proof is the same).

We also need an additional estimate for $\sum_{g\in G}\chi(\ell_g(\vec q))$. For this, we first use \cref{eq:m-1-STS} to see that $|G|^{-1}\sum_{g\in G}\ell_g(\vec q)=|\vec q|/m=1-O(1/\log B)$. Then, note that $\chi$ is convex and continuous on $[0,1]$, so by Jensen's inequality,
\begin{equation}
    \sum_{g\in G}\chi(\ell_g(\vec q))\ge |G|\chi(|\vec q|/m)=|G|(1+o_{B\to \infty }(1))\ge 3m-(\varepsilon/4)m\label{eq:new-step-STS}
\end{equation}
for large $B$. The desired result \cref{eq:goal-STS-binomial-reduction} then follows from \cref{eq:new-step-STS,eq:previous-step-3}.

We only need to prove the upper bound, as the lower bound was already proved by Kwan, Sah, Sawhney and Simkin~\cite[Theorem~1.3]{KSSS24}. We work in setting (1) of \cref{def:STS-H}.

Let $\vec q=(q_{xyz})_{xyz\in K_n^{(3)}}$ be a weighting which minimises $\operatorname D_{\mathrm{KL}}(\vec{q}\,\|\,m/N)+\mathcal{H}_{4}(\vec{q})$, over all such weightings with sum of entries exactly $m$. By \cref{lem:truncation-lower} we have $q_{xyz}\le O(m/N)=O(1/n)$ for all $xyz\in K_n^{(3)}$. We compute
\begin{align*}
\operatorname D_{\mathrm{KL}}(\vec{q}\,\|\,m/N)+\mathcal{H}_{4}(\vec{q}) & =
\sum_{xyz\in K_n^{(3)}}q_{xyz}\log\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{q_{xyz}}{m/N}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)-\sum_{xyz\in K_n^{(3)}}q_{xyz}+\sum_{xyz\in K_n^{(3)}}\frac m N\\
&\qquad+\frac{1}{24}\sum_{\substack{x_0,x_1,y_0,y_1,z_0,z_1\in \operatorname V(K_{n}^{(3)})\\\text{distinct}}
